import React, { useState } from "react";
import axios from "axios";

const ApplyForm = ({ job }) => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    skillset: "",
    resumeUrl: "",
    jobId: job?._id || "",
    jobTitle: job?.title || "",
    location: job?.location || "",
    pincode: "",
    address: "",
    project: "",
    academic: {
      tenth: { score: "", school: "" },
      diploma: { score: "", college: "", stream: "" },
      graduation: { score: "", college: "", stream: "" },
      postGraduation: { score: "", college: "", stream: "" },
    },
  });

  const [resumeFile, setResumeFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");

  // Handle text input changes
  const handleChange = (e) => {
    const { name, value } = e.target;

    // Handle nested academic fields
    if (name.includes(".")) {
      const [level, field] = name.split(".");
      setFormData((prev) => ({
        ...prev,
        academic: {
          ...prev.academic,
          [level]: {
            ...prev.academic[level],
            [field]: value,
          },
        },
      }));
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }
  };

  // Handle resume upload
  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setResumeFile(file);
    setUploading(true);
    setMessage("Extracting details from your resume...");

    const formDataToSend = new FormData();
    formDataToSend.append("resume", file);

    try {
      const res = await axios.post("http://localhost:5000/api/upload-resume", formDataToSend, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      const { skillset, project, internships } = res.data;
      setFormData((prev) => ({
        ...prev,
        skillset: skillset || prev.skillset,
        project: project || prev.project,
      }));

      setMessage("✅ Resume uploaded and details extracted successfully!");
    } catch (err) {
      console.error("Error extracting resume:", err);
      setMessage("❌ Failed to extract details from the resume.");
    } finally {
      setUploading(false);
    }
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post("http://localhost:5000/api/applications", formData);
      setMessage(response.data.message || "Application submitted successfully!");
      setFormData({
        name: "",
        email: "",
        phone: "",
        skillset: "",
        resumeUrl: "",
        jobId: job?._id || "",
        jobTitle: job?.title || "",
        location: job?.location || "",
        pincode: "",
        address: "",
        project: "",
        academic: {
          tenth: { score: "", school: "" },
          diploma: { score: "", college: "", stream: "" },
          graduation: { score: "", college: "", stream: "" },
          postGraduation: { score: "", college: "", stream: "" },
        },
      });
      setResumeFile(null);
    } catch (err) {
      console.error("Error submitting application:", err);
      setMessage("❌ Failed to submit application.");
    }
  };

  return (
    <div className="apply-form-container" style={styles.container}>
      <h2 style={styles.heading}>Apply for {job?.title}</h2>
      <form onSubmit={handleSubmit} style={styles.form}>
        {/* Basic Info */}
        <div style={styles.section}>
          <label style={styles.label}>Full Name</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} required style={styles.input} />

          <label style={styles.label}>Email</label>
          <input type="email" name="email" value={formData.email} onChange={handleChange} required style={styles.input} />

          <label style={styles.label}>Phone</label>
          <input type="text" name="phone" value={formData.phone} onChange={handleChange} required style={styles.input} />
        </div>

        {/* Resume Upload */}
        <div style={styles.section}>
          <label style={styles.label}>Upload Resume (PDF)</label>
          <input type="file" accept="application/pdf" onChange={handleFileChange} style={styles.inputFile} />
          {uploading && <p style={styles.info}>Extracting details...</p>}
        </div>

        {/* Auto-filled Info */}
        <div style={styles.section}>
          <label style={styles.label}>Skills</label>
          <textarea name="skillset" value={formData.skillset} onChange={handleChange} rows="3" style={styles.textarea} />

          <label style={styles.label}>Project Details</label>
          <textarea name="project" value={formData.project} onChange={handleChange} rows="3" style={styles.textarea} />
        </div>

        {/* Address Info */}
        <div style={styles.section}>
          <label style={styles.label}>Address</label>
          <textarea name="address" value={formData.address} onChange={handleChange} rows="2" style={styles.textarea} />

          <label style={styles.label}>Pincode</label>
          <input type="text" name="pincode" value={formData.pincode} onChange={handleChange} style={styles.input} />
        </div>

        {/* Academic Info */}
        <div style={styles.section}>
          <h4 style={styles.subHeading}>Academic Details</h4>

          <label style={styles.label}>10th Score</label>
          <input type="text" name="tenth.score" value={formData.academic.tenth.score} onChange={handleChange} style={styles.input} />

          <label style={styles.label}>10th School</label>
          <input type="text" name="tenth.school" value={formData.academic.tenth.school} onChange={handleChange} style={styles.input} />

          <label style={styles.label}>Graduation College</label>
          <input type="text" name="graduation.college" value={formData.academic.graduation.college} onChange={handleChange} style={styles.input} />

          <label style={styles.label}>Graduation Stream</label>
          <input type="text" name="graduation.stream" value={formData.academic.graduation.stream} onChange={handleChange} style={styles.input} />

          <label style={styles.label}>Graduation Score</label>
          <input type="text" name="graduation.score" value={formData.academic.graduation.score} onChange={handleChange} style={styles.input} />
        </div>

        <button type="submit" style={styles.button} disabled={uploading}>
          {uploading ? "Please wait..." : "Submit Application"}
        </button>

        {message && <p style={styles.message}>{message}</p>}
      </form>
    </div>
  );
};

export default ApplyForm;

// ==================== INLINE STYLES ====================
const styles = {
  container: {
    maxWidth: "600px",
    margin: "20px auto",
    background: "#fff",
    padding: "25px 30px",
    borderRadius: "12px",
    boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
  },
  heading: {
    textAlign: "center",
    marginBottom: "20px",
    color: "#333",
  },
  section: {
    marginBottom: "20px",
  },
  label: {
    display: "block",
    fontWeight: "bold",
    marginBottom: "5px",
    color: "#444",
  },
  input: {
    width: "100%",
    padding: "8px 10px",
    border: "1px solid #ccc",
    borderRadius: "6px",
    marginBottom: "10px",
  },
  inputFile: {
    width: "100%",
    padding: "5px",
    border: "1px dashed #888",
    borderRadius: "6px",
  },
  textarea: {
    width: "100%",
    padding: "8px 10px",
    border: "1px solid #ccc",
    borderRadius: "6px",
    marginBottom: "10px",
  },
  button: {
    width: "100%",
    background: "linear-gradient(135deg,#667eea,#764ba2)",
    color: "#fff",
    padding: "12px",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    cursor: "pointer",
  },
  info: { fontStyle: "italic", color: "#555" },
  message: { marginTop: "15px", textAlign: "center", color: "#222" },
  subHeading: { marginBottom: "8px", color: "#555" },
};
